    "author": "Room to Read Global Initiative (Room to Read / CC BY 4.0)",
    "description": "An inspiring read-along story for young explorers about leo's rocket adventure to mars (chapter 3).",
    "coverUrl": "https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=720&h=440&fit=crop",
