    "author": "Arleen Amidjaja • Ilus. Bella Ansori (Let's Read Indonesia / CC BY 4.0)",
    "description": "Cerita membaca bersuara untuk anak usia sekolah tentang misteri lentera kunang-kunang desa sukamaju.",
