    "createdAt": "2026-01-16T11:00:00.000Z",
    "pages": [
      {
        "pageNumber": 1,
        "text": "Si Kancil berdiri di tepi sungai berarus deras dan ingin menyeberang untuk memetik buah ranum.",
        "imageUrl": "https://images.unsplash.com/photo-1448375240586-882707db888b?w=720&h=440&fit=crop",
        "illustrationEmoji": "🦌🐊",
        "bgColor": "#312E81"
      },
      {
        "pageNumber": 2,
        "text": "Melihat sekumpulan buaya lapar, Kancil dengan cerdik meminta mereka berbaris rapi untuk dihitung.",
        "imageUrl": "https://images.unsplash.com/photo-1511497584788-87676104235f?w=720&h=440&fit=crop",
        "illustrationEmoji": "🦌🐊",
        "bgColor": "#4C1D95"
      },
      {
        "pageNumber": 3,
        "text": "Satu, dua, tiga, Kancil melompati punggung buaya satu demi satu hingga tiba di seberang.",
        "imageUrl": "https://images.unsplash.com/photo-1473448912268-2022ce9509d8?w=720&h=440&fit=crop",
        "illustrationEmoji": "🦌🐊",
        "bgColor": "#581C87"
      },
      {
        "pageNumber": 4,
        "text": "Kancil berterima kasih sambil tersenyum ramah, mengajarkan pentingnya ketenangan dalam berpikir.",
        "imageUrl": "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=720&h=440&fit=crop",
        "illustrationEmoji": "🦌🐊",
        "bgColor": "#701A75"
      }
    ]
